from h import *
O=[]
O.append(R(6399816,None,
("سمك القد المشوي بالشواية العلوية","توصي الجمعية الأمريكية للسكري والجمعية الأمريكية للقلب بتناول حصتين (2) من السمك على الأقل أسبوعيًا. سمك القد المشوي هذا خيار لذيذ. وإن لم تكن من محبي سمك القد، فيمكنك استبداله بأي سمك آخر. اضغط هنا للمزيد من الوصفات المفيدة للقلب","4","1 شريحة",
["1 بخّة (0.25 غرام) بخاخ طهي غير لاصق","3 ملعقة كبيرة مايونيز خفيف","½ حبة ليمون عصير الليمون","½ ملعقة صغيرة بابريكا","1 ملعقة صغيرة بقدونس (مجفف)","¼ ملعقة صغيرة فلفل أسود","4 شرائح سمك قد كاملة (نحو 1 رطل في المجموع)","1 ملعقة كبيرة جبن بارميزان (مبشور)"],
["سخّن الشواية العلوية مسبقًا. رش صينية خبز أو صينية الشواية ببخاخ الطهي.","في وعاء صغير، اخلط المايونيز وعصير الليمون والبابريكا والبقدونس والفلفل الأسود المطحون.","ضع شرائح سمك القد على صينية الشواية ووزّع خليط المايونيز بالتساوي على الشرائح. رش جبن البارميزان فوق الشرائح.","اشوِ الشرائح تحت الشواية العلوية لمدة 8-10 دقائق."],[],[])))
O.append(R(6399914,
("Granita de durazno y jengibre","Este postre apto para la diabetes presenta una refrescante granita de durazno y jengibre con un vivo sabor a limón y arce, que la convierte en un postre helado ligero y satisfactorio.","4","1/2 taza",
["4 duraznos medianos (maduros, pelados, sin hueso y cortados en cuartos)","1 cucharada de jengibre fresco (pelado y rallado)","3 cucharadas de jarabe sabor arce sin azúcar","1 cucharada de jugo de limón"],
["En una licuadora, combine los duraznos, el jengibre, el jarabe de arce y el jugo fresco de limón.","Licúe la mezcla hasta obtener un puré suave.","Vierta el puré de durazno y jengibre en una capa uniforme en un molde poco profundo apto para congelador.","Coloque el molde en el congelador y deje que cuaje durante aproximadamente 1 hora.","Después de 1 hora, con un tenedor raspe los bordes congelados hacia el centro. Repita este proceso cada 30 minutos durante las siguientes 3 a 4 horas, o hasta que toda la mezcla esté granulada y congelada.","Cuando la granita haya alcanzado la textura deseada, sírvala con una cuchara en tazones pequeños."],[],[]),
("غرانيتا الخوخ والزنجبيل","يضم هذا الحلوى المناسبة لمرضى السكري غرانيتا منعشة بالخوخ والزنجبيل بنكهة الليمون الزاهية وشراب القيقب، لتكون حلوى مثلجة خفيفة ومُرضية.","4","½ كوب",
["4 حبة خوخ متوسطة (ناضجة، مقشرة ومنزوعة النوى ومقطعة أرباعًا)","1 ملعقة كبيرة زنجبيل طازج (مقشر ومبشور)","3 ملعقة كبيرة شراب بنكهة القيقب خالٍ من السكر","1 ملعقة كبيرة عصير ليمون"],
["في الخلاط، اخلط الخوخ والزنجبيل وشراب القيقب وعصير الليمون الطازج.","اخلط المزيج حتى يصبح هريسًا ناعمًا.","صب هريس الخوخ والزنجبيل في طبقة متساوية في وعاء غير عميق صالح للفريزر.","ضع الوعاء في الفريزر واتركه يتجمد لمدة ساعة (1) تقريبًا.","بعد مرور ساعة (1)، استخدم شوكة لكشط الحواف المتجمدة نحو الوسط. كرر هذه العملية كل 30 دقيقة خلال الساعات 3–4 التالية أو حتى يصبح الخليط كله محببًا ومتجمدًا.","عندما تصل الغرانيتا إلى القوام المطلوب، اغرفها وقدّمها في أوعية صغيرة."],[],[])))
